import math


class Pulse:
    def __init__(self, speed=4):
        if isinstance(speed, bool) or not isinstance(speed, int) or speed <= 0:
            raise ValueError("speed must be a positive integer")
        self.x = 0
        self.y = 0
        self.speed = speed
        self.active = False

    @staticmethod
    def _coordinate(value, name):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError(f"{name} must be numeric")
        if not math.isfinite(value):
            raise ValueError(f"{name} must be finite")
        return value

    def fire(self, source_x, source_y=0):
        x = self._coordinate(source_x, "source_x")
        y = self._coordinate(source_y, "source_y")
        if self.active:
            return False
        self.x = x
        self.y = y
        self.active = True
        return True

    def advance(self, limit=100):
        boundary = self._coordinate(limit, "limit")
        if not self.active:
            return False
        self.y += self.speed
        if self.y >= boundary:
            self.active = False
            return False
        return True

    def snapshot(self):
        return {"x": self.x, "y": self.y, "speed": self.speed, "active": self.active}
